const doc = $json;
const content = doc?.body?.content || [];
let fullText = '';
for (const el of content) {
  const p = el.paragraph;
  if (!p?.elements) continue;
  for (const pe of p.elements) {
    const t = pe.textRun?.content;
    if (t) fullText += t;
  }
}
return [{ json: { docId: doc.documentId, fullText } }];

const allJobs = $input.all();
const config = $('Workflow Configuration').first().json;
const supabaseUrl = config.supabaseUrl;
const supabaseKey = config.supabaseKey;
const existingUrls = new Set();
async function checkJobExists(jobUrl) {
  try {
    const response = await fetch(`${supabaseUrl}/rest/v1/applications?job_url=eq.${encodeURIComponent(jobUrl)}&select=job_url`, { method: 'GET', headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' } });
    if (!response.ok) return null;
    const data = await response.json();
    return data.length > 0 ? jobUrl : null;
  } catch (error) { return null; }
}
const checkPromises = allJobs.map(job => checkJobExists(job.json.jobLink));
const results = await Promise.all(checkPromises);
for (const url of results) { if (url) existingUrls.add(url); }
const newJobs = allJobs.filter(job => !existingUrls.has(job.json.jobLink));
return newJobs;

// Extract the model's text from whatever shape the chain returns
let txt =
  $json.text
  ?? $json.output
  ?? $json.response?.generations?.[0]?.[0]?.text
  ?? '';

txt = String(txt).trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/, '')
  .replace(/```\s*$/, '')
  .trim();

let candidate;
try {
  candidate = JSON.parse(txt);
} catch (e) {
  throw new Error('Profile Parser did not return valid JSON: ' + e.message + ' :: ' + txt.slice(0, 300));
}
return [{ json: { candidate } }];

const candidate = $('Parse Candidate JSON').first().json.candidate || {};
const avoidTitles = (candidate.do_not_apply || []).map(s => s.toLowerCase());
const avoidIndustries = ((candidate.targeting && candidate.targeting.industries_avoid) || []).map(s => s.toLowerCase());

// German + English equivalents so the title filter is robust
const extra = ['working student','werkstudent','intern','internship','praktikum','praktikant',
               'master thesis','masterarbeit','ausbildung','apprentice','trainee','duales studium'];
const blockTitle = [...new Set([...avoidTitles, ...extra])].filter(Boolean);

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const title = (j.title || '').toLowerCase();
  const hay = `${j.title || ''} ${j.jobDescription || ''}`.toLowerCase();
  const blockedByTitle = blockTitle.some(t => title.includes(t));
  const blockedByIndustry = avoidIndustries.some(t => t && hay.includes(t));
  if (blockedByTitle || blockedByIndustry) continue;
  out.push(item);
}
return out;

parameters.text:
=You are a strict technical recruiter. Evaluate how well the candidate fits ONE job. Return JSON ONLY ; no markdown, no commentary.

SCORING RULES:
- Score 0-100 based ONLY on technical and domain fit between the candidate's skills/experience and the job requirements.
- German (or any local-language) proficiency MUST NOT affect the score. Ignore all language requirements when scoring.
- Never claim skills listed in DO_NOT_CLAIM. If the job requires them, put them in "missing_skills".
- Treat keyword aliases as equivalent (e.g. K8s = Kubernetes) so wording never lowers the score.
- "should_apply" is true only if the role matches the candidate's target titles/seniority AND does not explicitly refuse visa sponsorship.
- "recommended_keywords": terms from the job the candidate can TRUTHFULLY add (supported by real experience).

Return EXACTLY this shape:
{"match_score": 0, "should_apply": false, "missing_skills": [], "strengths": [], "recommended_keywords": [], "reason": ""}

CANDIDATE:
Target titles: {{ JSON.stringify($('Parse Candidate JSON').first().json.candidate.targeting.titles) }}
Seniority: {{ $('Parse Candidate JSON').first().json.candidate.targeting.seniority }}
Skills: {{ JSON.stringify($('Parse Candidate JSON').first().json.candidate.skills) }}
Keyword aliases: {{ JSON.stringify($('Parse Candidate JSON').first().json.candidate.keyword_aliases) }}
DO_NOT_CLAIM: {{ JSON.stringify($('Parse Candidate JSON').first().json.candidate.do_not_claim) }}

JOB:
Title: {{ $json.title }}
Company: {{ $json.company }}
Description: {{ $json.jobDescription }}

