// pull out the FIRST complete {...} object, ignoring code fences / trailing junk
function extractJson(s) {
  const start = s.indexOf('{');
  if (start < 0) return s;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const ch = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
    } else if (ch === '"') inStr = true;
    else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) return s.slice(start, i + 1); }
  }
  return s.slice(start);
}

let raw = $json.text ?? $json.output ?? ($json.response?.generations?.[0]?.[0]?.text) ?? '';
raw = String(raw).trim().replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim();

let resume;
try { resume = JSON.parse(extractJson(raw)); }
catch (e) { throw new Error('Resume Builder returned invalid JSON: ' + e.message + ' :: ' + raw.slice(0,300)); }

const c   = $('Parse Candidate JSON').first().json.candidate || {};
const id  = c.identity || {};
const job = $('Parse Match JSON').item.json;

// dedupe experience by company+title+dates, merging bullets
const seen = new Map();
for (const e of (resume.experience || [])) {
  const key = `${e.company||''}|${e.title||''}|${e.dates||''}`;
  if (seen.has(key)) seen.get(key).bullets.push(...(e.bullets || []));
  else seen.set(key, { ...e, bullets: [...(e.bullets || [])] });
}
resume.experience = [...seen.values()];

// keep ONLY real companies from the profile (drops injected target job / hallucinations)
const realCompanies = new Set((c.experience || []).map(e => (e.company||'').toLowerCase().trim()));
resume.experience = resume.experience.filter(e => realCompanies.has((e.company||'').toLowerCase().trim()));

// order to match the profile (reverse-chronological source order)
const order = (c.experience || []).map(e => `${e.company||''}|${e.title||''}`);
resume.experience.sort((a, b) => {
  const ia = order.indexOf(`${a.company||''}|${a.title||''}`);
  const ib = order.indexOf(`${b.company||''}|${b.title||''}`);
  return (ia < 0 ? 999 : ia) - (ib < 0 ? 999 : ib);
});

// projects: keep only those with bullets, cap at 3
resume.projects = (resume.projects || [])
  .filter(p => Array.isArray(p.bullets) && p.bullets.length > 0)
  .slice(0, 3);

// merge identity/contact
resume.name = id.name || '';
resume.contact = {
  location: id.location || '', phone: id.phone || '', email: id.email || '',
  linkedin: id.linkedin || '', github: id.github || '', portfolio: id.portfolio || '', medium: id.medium || ''
};

return { json: {
  resume,
  company: job.company || '', title: job.title || '', jobLink: job.jobLink || '',
  postedAt: job.postedAt || '', location: job.location || '', match: job.match || {}
}};

const r = $json.resume || {};
const c = $('Parse Candidate JSON').first().json.candidate || {};
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ct = r.contact || {};
const links = [];
if (ct.location) links.push(esc(ct.location));
if (ct.phone) links.push(esc(ct.phone));
if (ct.email) links.push(`<a href="mailto:${esc(ct.email)}">${esc(ct.email)}</a>`);
if (ct.linkedin) links.push(`<a href="${esc(ct.linkedin)}">LinkedIn</a>`);
if (ct.github) links.push(`<a href="${esc(ct.github)}">GitHub</a>`);
if (ct.portfolio) links.push(`<a href="${esc(ct.portfolio)}">Portfolio</a>`);
if (ct.medium) links.push(`<a href="${esc(ct.medium)}">Medium</a>`);

let h = '';
h += `<h1 style="text-align:center;margin-bottom:2px">${esc(r.name)}</h1>`;
h += `<p style="text-align:center">${links.join(' &nbsp;•&nbsp; ')}</p>`;
if (r.summary) h += `<h2>Summary</h2><p>${esc(r.summary)}</p>`;

if ((r.experience||[]).length) {
  h += `<h2>Professional Experience</h2>`;
  for (const e of r.experience) {
    h += `<p style="margin-bottom:0"><b>${esc(e.company)}</b> ; ${esc(e.location)}<br><i>${esc(e.title)}</i> · ${esc(e.dates)}</p>`;
    if ((e.bullets||[]).length) h += `<ul>`+e.bullets.map(b=>`<li>${esc(b)}</li>`).join('')+`</ul>`;
  }
}
if ((r.projects||[]).length) {
  h += `<h2>Projects</h2>`;
  for (const p of r.projects) {
    const name = p.link ? `<a href="${esc(p.link)}">${esc(p.name)}</a>` : esc(p.name);
    h += `<p style="margin-bottom:0"><b>${name}</b></p>`;
    if ((p.bullets||[]).length) h += `<ul>`+p.bullets.map(b=>`<li>${esc(b)}</li>`).join('')+`</ul>`;
  }
}
const edu = c.education || [];
if (edu.length) {
  h += `<h2>Education</h2>`;
  for (const ed of edu) {
    h += `<p style="margin-bottom:0"><b>${esc(ed.degree)}</b> ; ${esc(ed.institution)}${ed.city?', '+esc(ed.city):''}<br><i>${esc(ed.dates)}</i>${ed.thesis?` · Thesis: ${esc(ed.thesis)}`:''}</p>`;
  }
}
if (r.skills && Object.keys(r.skills).length) {
  h += `<h2>Skills</h2>`;
  for (const [cat, items] of Object.entries(r.skills)) {
    h += `<p style="margin:0"><b>${esc(cat)}:</b> ${esc((items||[]).join(', '))}</p>`;
  }
}
const safe = s => String(s||'').replace(/[\/\\:*?"<>|]/g,'').slice(0,80);
const filename = `${safe($json.company)} - ${safe($json.title)} - ${$json.postedAt || new Date().toISOString().slice(0,10)}`;
return { json: { html: `<html><body>${h}</body></html>`, filename,
  company: $json.company, title: $json.title, jobLink: $json.jobLink, postedAt: $json.postedAt, match: $json.match, resume: r } };

const html = $json.html;
const boundary = '----n8nBoundary' + Date.now();
const metadata = JSON.stringify({ name: $json.filename, mimeType: 'application/vnd.google-apps.document' });
const body =
  `--${boundary}
Content-Type: application/json; charset=UTF-8

${metadata}
` +
  `--${boundary}
Content-Type: text/html; charset=UTF-8

${html}
` +
  `--${boundary}--`;
return { json: { ...$json, multipartBody: body, boundary } };

const src   = $('Parse Resume JSON').item.json;
const docId = $('Create Google Doc').item.json.id;
const pdfId = $json.id;   // Upload PDF to Drive is the direct input
const m = src.match || {};
const docLink = docId ? `https://docs.google.com/document/d/${docId}/edit` : '';
const pdfLink = pdfId ? `https://drive.google.com/file/d/${pdfId}/view` : '';
return { json: {
  company: src.company, title: src.title, jobLink: src.jobLink, postedAt: src.postedAt,
  match_score: m.match_score ?? null, should_apply: m.should_apply ?? null,
  missing_skills: m.missing_skills ?? [], strengths: m.strengths ?? [],
  recommended_keywords: m.recommended_keywords ?? [], reason: m.reason ?? '',
  docLink, pdfLink,
  application_json: { ...src, docLink, pdfLink }
}};

const results = $input.all();
const jobs = [];
const seen = new Set();

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?(li|p|div|h[1-6])[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

for (const item of results) {
  const j = item.json;
  const jobLink = j.link || j.jobUrl || j.url || '';
  if (seen.has(jobLink) || !jobLink) continue;

  const postedAt = j.postedAt || '';
  const sevenDaysAgo = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
  if (postedAt < sevenDaysAgo) continue;

  const jobDescription = j.descriptionHtml
    ? stripHtml(j.descriptionHtml)
    : (j.descriptionText || '');
  if (!jobDescription || jobDescription.length < 50) continue;

  jobs.push({
    title:          j.title          || 'No Title',
    company:        j.companyName    || 'Unknown Company',
    location:       j.location       || 'Unknown Location',
    postedAt,
    employmentType: j.employmentType || '',
    seniorityLevel: j.seniorityLevel || '',
    jobLink,
    jobDescription
  });

  seen.add(jobLink);
  if (jobs.length >= 20) break;
}

return jobs.map(job => ({ json: job }));

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const today = new Date().toISOString().slice(0,10);
const apps = $('Assemble Application').all().map(i => i.json);

const scoreColor = s => s >= 80 ? '#16a34a' : s >= 70 ? '#d97706' : '#6b7280';
const chip = (t, bg, fg) => `<span style="display:inline-block;background:${bg};color:${fg};font-size:12px;line-height:1;padding:5px 9px;border-radius:999px;margin:0 4px 4px 0">${esc(t)}</span>`;
const btn = (href, label, bg) => href ? `<a href="${href}" style="display:inline-block;background:${bg};color:#fff;text-decoration:none;font-size:13px;font-weight:600;padding:8px 14px;border-radius:8px;margin:0 6px 0 0">${esc(label)}</a>` : '';

let cards = '';
for (const a of apps) {
  const sc = Number(a.match_score) || 0;
  const strengths = (a.strengths||[]).map(t => chip(t, '#dcfce7', '#166534')).join('') || '<span style="color:#9ca3af;font-size:13px">;</span>';
  const missing = (a.missing_skills||[]).map(t => chip(t, '#fef3c7', '#92400e')).join('') || '<span style="color:#9ca3af;font-size:13px">None 🎉</span>';
  cards += `
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e5e7eb;border-radius:12px;margin:0 0 16px;background:#fff">
    <tr><td style="padding:18px 20px">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
        <td style="vertical-align:top">
          <div style="font-size:17px;font-weight:700;color:#111827">${esc(a.company)}</div>
          <div style="font-size:14px;color:#4b5563;margin-top:2px">${esc(a.title)}</div>
          ${a.location ? `<div style="font-size:12px;color:#9ca3af;margin-top:2px">${esc(a.location)}</div>` : ''}
        </td>
        <td style="vertical-align:top;text-align:right;white-space:nowrap">
          <span style="display:inline-block;background:${scoreColor(sc)};color:#fff;font-size:15px;font-weight:700;padding:6px 12px;border-radius:999px">${sc}<span style="font-size:11px;font-weight:500">/100</span></span>
        </td>
      </tr></table>
      <div style="margin-top:14px">
        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#6b7280;font-weight:600;margin-bottom:6px">Strengths</div>
        <div>${strengths}</div>
      </div>
      <div style="margin-top:12px">
        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#6b7280;font-weight:600;margin-bottom:6px">Missing / to address</div>
        <div>${missing}</div>
      </div>
            ${a.reason ? `<div style="margin-top:12px;font-size:13px;color:#4b5563;background:#f9fafb;border-left:3px solid #d1d5db;padding:9px 12px;border-radius:0 6px 6px 0"><span style="font-weight:600;color:#374151">Why:</span> ${esc(a.reason)}</div>` : ''}
      <div style="margin-top:16px">
        ${btn(a.jobLink, 'View Job', '#2563eb')}
        ${btn(a.docLink, 'Edit Resume (Doc)', '#7c3aed')}
        ${btn(a.pdfLink, 'Download PDF', '#111827')}
      </div>
    </td></tr>
  </table>`;
}

const avg = apps.length ? Math.round(apps.reduce((s,a)=>s+(Number(a.match_score)||0),0)/apps.length) : 0;
const body = `
<div style="background:#f3f4f6;padding:24px 0;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center">
    <table role="presentation" width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%">
      <tr><td style="padding:0 8px">
        <div style="font-size:22px;font-weight:800;color:#111827">Your ATS Applications</div>
        <div style="font-size:13px;color:#6b7280;margin:4px 0 18px">${apps.length} match${apps.length===1?'':'es'} • avg fit ${avg}/100 • ${new Date().toLocaleString()}</div>
      </td></tr>
      <tr><td style="padding:0 8px">${cards}</td></tr>
      <tr><td style="padding:8px 8px 0;text-align:center;color:#9ca3af;font-size:11px">Generated automatically by your Job Apply Bot • ${today}</td></tr>
    </table>
  </td></tr></table>
</div>`;

return [{ json: { subject: `🎯 ${apps.length} ATS application${apps.length===1?'':'s'} ready ; ${today}`, body } }];
